# --------------------------------------------------------------------------
# 1. Lectura robusta de los CSV "doblemente escapados" de Directus
# --------------------------------------------------------------------------

REC_START = re.compile(r'^"?\d+,')
NEWLINE_MARKER = '\x01'


def read_raw_lines(path):
    with open(path, encoding='utf-8-sig') as f:
        return f.read().split('\n')


def merge_records(lines):
    """Une líneas físicas en registros lógicos. Un registro nuevo empieza
    siempre por '<id numérico>,'; los campos de texto largo (p.ej.
    comentarios) pueden contener saltos de línea reales que hay que volver
    a pegar al registro anterior."""
    recs = []
    buf = None
    for line in lines:
        if line == '':
            continue
        if REC_START.match(line):
            if buf is not None:
                recs.append(buf)
            buf = line
        else:
            buf = (buf + '\n' + line) if buf is not None else line
    if buf is not None:
        recs.append(buf)
    return recs


def fix_embedded_newlines(rec):
    """Un salto de línea real dentro de un campo de texto aparece en
    origen como cierre de comillas + ';' + salto de línea + apertura de
    comillas. Se sustituye por un marcador de un solo carácter para que no
    rompa el parseo CSV, y se restaura después."""
    return re.sub(r'";\n"', NEWLINE_MARKER, rec)


def normalize_record(rec):
    rec = fix_embedded_newlines(rec)
    rec = rec.replace('""', '"')
    if rec.startswith('"'):
        rec = rec[1:]
    rec = rec.rstrip('\n')
    if rec.endswith(';'):
        rec = rec[:-1]
    if rec.endswith('"'):
        rec = rec[:-1]
    return rec


def find_bracket_span(text, start_marker='[{'):
    idx = text.find(start_marker)
    if idx == -1:
        return None
    depth = 0
    for i in range(idx, len(text)):
        ch = text[i]
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
            if depth == 0:
                return idx, i + 1
    return idx, len(text)


def parse_header(first_line):
    h = first_line.replace('""', '"')
    if h.startswith('"'):
        h = h[1:]
    if h.endswith('"'):
        h = h[:-1]
    if h.endswith(';'):
        h = h[:-1]
    return [x.strip('"').rstrip(';') for x in h.split('","')]


def parse_row(record, n_cols, json_marker='[{'):
    span = find_bracket_span(record, json_marker)
    if span is None:
        core_text = record
        if core_text.count('"') % 2 == 1:
            core_text += '"'
        row = next(csv.reader(io.StringIO(core_text)), [])
        blob = ''
    else:
        start, end = span
        before, blob, after = record[:start], record[start:end], record[end:]
        core_text = before + '"__JSON__"' + after
        if core_text.count('"') % 2 == 1:
            core_text += '"'
        row = next(csv.reader(io.StringIO(core_text)), [])
    if len(row) < n_cols:
        row += [''] * (n_cols - len(row))
    row = [v.replace(NEWLINE_MARKER, '\n').strip() for v in row[:n_cols]]
    return row, blob.replace(NEWLINE_MARKER, '\n')


def collapse_quotes(text):
    while '""' in text:
        text = text.replace('""', '"')
    return text


def extract_json_pairs(blob, list_key, obj_key):
    """Extrae pares (lista_valores_de list_key, valor_de obj_key) de un
    bloque de relación tipo [{"list_key":[...], ...:{"obj_key":"X"}}, ...]
    Tolerante a la profundidad de escapado (variable en origen)."""
    if not blob:
        return []
    blob = collapse_quotes(blob)
    lists = re.findall(list_key + r'"?\s*:?\s*\[([^\]]*)\]', blob)
    objs = re.findall(obj_key + r'"?\s*:?\s*"([^"]+)"', blob)
    n = max(len(lists), len(objs))
    pairs = []
    for i in range(n):
        raw_list = lists[i] if i < len(lists) else ''
        values = re.findall(r'"([^"]+)"', raw_list)
        obj_val = objs[i] if i < len(objs) else ''
        pairs.append((values, obj_val))
    return pairs


def extract_json_values(blob, key):
    if not blob:
        return []
    blob = collapse_quotes(blob)
    return re.findall(key + r'"?\s*:?\s*"([^"]+)"', blob)


def load_directus_csv(path, json_marker='[{'):
    """Devuelve (cabecera, lista_de_(campos, blob_json)). Si el fichero ya
    es un CSV normal (sin el doble escapado), también funciona: en ese
    caso simplemente no habrá nada que "colapsar" y el resultado es el
    mismo que con csv.DictReader."""
    raw_lines = read_raw_lines(path)
    raw_lines = [l for l in raw_lines if l.strip() != '']
    if not raw_lines:
        return [], []
    hdr = parse_header(raw_lines[0])
    records = merge_records(raw_lines[1:])
    n = len(hdr)
    out = []
    for rec in records:
        norm = normalize_record(rec)
        fields, blob = parse_row(norm, n, json_marker)
        out.append((fields, blob))
    return hdr, out


def as_dicts(hdr, rows):
    return [dict(zip(hdr, fields)) for fields, _blob in rows]


# --------------------------------------------------------------------------
# 2. Localización de ficheros de entrada
# --------------------------------------------------------------------------

def find_input(explicit_path, prefix):
    if explicit_path:
        return explicit_path
    candidates = sorted(glob.glob(f'{prefix}*.csv')) + sorted(glob.glob(f'*{prefix}*.csv'))
    candidates = list(dict.fromkeys(candidates))
    if not candidates:
        sys.exit(f'No encuentro ningún CSV de "{prefix}" en el directorio actual. '
                  f'Indícalo con --{prefix.lower()}.')
    return candidates[0]


# --------------------------------------------------------------------------
# 3. Construcción del modelo de datos del informe
# --------------------------------------------------------------------------

def build_model(path_organismos, path_contactos, path_sistemas):
    hdr_o, rows_o = load_directus_csv(path_organismos)
    hdr_c, rows_c = load_directus_csv(path_contactos)
    hdr_s, rows_s = load_directus_csv(path_sistemas)

    organismos = as_dicts(hdr_o, rows_o)
    organismos = [o for o in organismos if o.get('acronimo_org')]
    organismos.sort(key=lambda o: (o.get('dto_estruc') or '', o.get('acronimo_org') or ''))

    # --- contactos por organismo -----------------------------------------
    contactos_por_org = defaultdict(list)
    for fields, blob in rows_c:
        c = dict(zip(hdr_c, fields))
        pairs = extract_json_pairs(blob, 'ambito_funcional_contacto', 'acronimo_org')
        # agrupar por organismo (un contacto puede repetirse si tiene
        # varias entradas de relación para el mismo organismo)
        ambitos_por_org = defaultdict(list)
        for ambitos, org in pairs:
            if not org:
                continue
            for a in ambitos:
                if a not in ambitos_por_org[org]:
                    ambitos_por_org[org].append(a)
            if not ambitos:
                ambitos_por_org[org]  # asegura la entrada aunque no traiga ámbito
        for org, ambitos in ambitos_por_org.items():
            contactos_por_org[org].append({
                'nombre': c.get('Nombre') or c.get('alias') or '',
                'apellidos': c.get('Apellidos') or '',
                'alias': c.get('alias') or '',
                'correo': c.get('correo_corporativo') or '',
                'tfno': c.get('tfno_corporativo') or '',
                'ambitos': ambitos,
            })
    for org in contactos_por_org:
        contactos_por_org[org].sort(key=lambda c: (c['apellidos'], c['nombre']))

    # --- sistemas por organismo -------------------------------------------
    sistemas_por_org = defaultdict(list)
    for fields, blob in rows_s:
        s = dict(zip(hdr_s, fields))
        org = s.get('organismo.acronimo_org') or s.get('organismo') or ''
        if not org:
            continue
        areas = extract_json_values(blob, 'nombre_area')
        sistemas_por_org[org].append({
            'nombre': s.get('nombre_sistema') or '(sin nombre)',
            'categ_ens': s.get('categ_ENS') or '',
            'conformidad': (s.get('conformidad_ens') or '').strip().lower() == 'true',
            'tto_datos': s.get('tto_datos_personales') or '',
            'id_conformidad': s.get('id_conformidad.Nro_conformidad') or '',
            'areas': areas,
            'estado': s.get('status') or '',
        })
    for org in sistemas_por_org:
        sistemas_por_org[org].sort(key=lambda s: s['nombre'].lower())

    return organismos, contactos_por_org, sistemas_por_org


CATEGORIAS_ENS = ['1-BÁSICA', '2-MEDIA', '3-ALTA']


def compute_stats(sistemas):
    total = len(sistemas)
    por_categ = Counter(s['categ_ens'] or 'Sin categoría' for s in sistemas)
    # aseguramos que las tres categorías ENS aparezcan siempre, aunque sea con 0
    for categ in CATEGORIAS_ENS:
        por_categ.setdefault(categ, 0)
    con_conformidad = sum(1 for s in sistemas if s['conformidad'])
    por_tto = Counter(s['tto_datos'] or 'Sin especificar' for s in sistemas)
    return {
        'total': total,
        'por_categ': por_categ,
        'con_conformidad': con_conformidad,
        'sin_conformidad': total - con_conformidad,
        'por_tto': por_tto,
    }


